import{M as a}from"./chunks/McpFeature.CtDtsj20.js";import{o as t,c as n,E as o,a3 as r}from"./chunks/framework.WFmvnizL.js";const h=JSON.parse(`{"title":"Nezha MCP — AI-Powered Server Management and Operations","description":"Connect Codex, OpenClaw, and Claude Code to Nezha MCP for natural-language fleet inspections, incident diagnosis, authorized commands, file management, and verified changes, with practical workflows and setup guidance.","frontmatter":{"title":"Nezha MCP — AI-Powered Server Management and Operations","description":"Connect Codex, OpenClaw, and Claude Code to Nezha MCP for natural-language fleet inspections, incident diagnosis, authorized commands, file management, and verified changes, with practical workflows and setup guidance.","outline":"deep","keywords":["Nezha MCP","AI operations","AI server management","Codex","OpenClaw","Claude Code","Model Context Protocol"],"faq":[{"question":"What is Nezha MCP?","answer":"Nezha MCP is a standard tool interface connecting AI assistants to servers. It provides server inventory, current state, remote commands, and file operations. AI interprets your goal; Nezha supplies the operational tools."},{"question":"Can I use it with Codex, OpenClaw, and Claude Code?","answer":"Clients supporting HTTP MCP and Bearer tokens can connect. Codex and Claude Code support remote MCP. OpenClaw needs an MCP client available to its current runtime or mcporter."},{"question":"Does Nezha include an AI model or chatbot?","answer":"No model is bundled. Nezha supplies monitoring and operations tools; your chosen AI client provides the model, conversation, reasoning, and workflow orchestration."},{"question":"Can MCP configure alerts, query historical metrics, or manage every Dashboard setting?","answer":"MCP provides server state, command, and file tools. Alert and task configuration, historical metrics, and other Dashboard settings require the Nezha admin UI or REST API."},{"question":"Can I automate incident response?","answer":"You can build workflows for diagnosis, authorized remediation, and verification. The client or external workflow provides scheduling, alert reception, and action confirmation. Nezha trigger tasks can execute reviewed scripts."},{"question":"Can data still reach an AI provider when Nezha is self-hosted?","answer":"Dashboard and server Agents can be self-hosted. With an external model, the client may send prompts, tool results, logs, or file contents to the model provider. Data handling depends on model deployment and the client's policies."}]},"headers":[],"relativePath":"en_US/guide/ai-operations.md","filePath":"en_US/guide/ai-operations.md","lastUpdated":1792674226000}`),s={name:"en_US/guide/ai-operations.md"},u=Object.assign(s,{setup(i){return(d,e)=>(t(),n("div",null,[o(a,{locale:"en"}),e[0]||(e[0]=r('<h2 id="turn-monitoring-data-into-action" tabindex="-1">Turn monitoring data into action <a class="header-anchor" href="#turn-monitoring-data-into-action" aria-label="Permalink to &quot;Turn monitoring data into action&quot;">​</a></h2><p><strong>Nezha MCP connects your AI assistant to servers you already monitor: check status, read logs, run commands, manage files, and verify the results.</strong> Describe your goal in natural language. AI organizes the steps; Nezha supplies the tools to work on your servers.</p><p>MCP (Model Context Protocol) is a standard for connecting AI to external tools. Reuse your existing Nezha connections without installing a model on every server. Your chosen AI client supplies the model and conversation.</p><h3 id="less-switching-between-tools" tabindex="-1">Less switching between tools <a class="header-anchor" href="#less-switching-between-tools" aria-label="Permalink to &quot;Less switching between tools&quot;">​</a></h3><ul><li><strong>Inspect multiple servers together.</strong> Gather findings in one report, reducing repeated logins, copied commands, and manual summaries.</li><li><strong>Move from finding issues to handling them.</strong> Go beyond explaining a metric: inspect relevant logs, run diagnostics, and carry out operations you authorize.</li><li><strong>Check again after a change.</strong> Compare configurations and service state before and after, so a successful command is backed by a service check.</li><li><strong>Use your familiar AI tools.</strong> Bring server management into Codex, OpenClaw, or Claude Code. You control which servers and operations they can access.</li></ul><h2 id="scenarios" tabindex="-1">Four practical ways to start <a class="header-anchor" href="#scenarios" aria-label="Permalink to &quot;Four practical ways to start {#scenarios}&quot;">​</a></h2><p>The first two scenarios draw on real fleet inspections and memory-alert investigations. The other two show workflows you can build.</p><h3 id="_1-fleet-inspection-find-the-servers-that-need-attention" tabindex="-1">1. Fleet inspection: find the servers that need attention <a class="header-anchor" href="#_1-fleet-inspection-find-the-servers-that-need-attention" aria-label="Permalink to &quot;1. Fleet inspection: find the servers that need attention&quot;">​</a></h3><blockquote><p>“Check disk space and software runtimes on all authorized servers. List issues that need attention and unreachable hosts separately. Do not change anything.”</p></blockquote><p>AI retrieves your server inventory, checks current state, runs inspection commands, and prepares a per-server report. Before security updates, it can also distinguish host software from container workloads to help establish what needs inspection and updating.</p><p><strong>What you get:</strong> Which servers need attention, the supporting findings, and what remains unknown. Offline or unchecked items stay separate from healthy ones.</p><h3 id="_2-incident-diagnosis-work-out-what-to-do-about-a-memory-alert" tabindex="-1">2. Incident diagnosis: work out what to do about a memory alert <a class="header-anchor" href="#_2-incident-diagnosis-work-out-what-to-do-about-a-memory-alert" aria-label="Permalink to &quot;2. Incident diagnosis: work out what to do about a memory alert&quot;">​</a></h3><blockquote><p>“Why does this server keep triggering memory alerts? Inspect processes and relevant logs, and suggest a response. Do not stop services yet.”</p></blockquote><p>AI examines current state, processes, and system logs to investigate causes and propose a targeted response. The process consuming the most memory is not necessarily the one the system terminated; checking logs helps avoid conclusions based on a single metric.</p><p><strong>What you get:</strong> Likely causes, supporting findings, and a response plan to review. For recurring response, a reviewed script can run through a Nezha alert-triggered task; alerts and tasks are configured through the admin UI or REST API.</p><h3 id="_3-configuration-changes-make-sure-the-service-works-afterward" tabindex="-1">3. Configuration changes: make sure the service works afterward <a class="header-anchor" href="#_3-configuration-changes-make-sure-the-service-works-afterward" aria-label="Permalink to &quot;3. Configuration changes: make sure the service works afterward&quot;">​</a></h3><blockquote><p>“Review this configuration change. Preserve the original and the diff, apply the approved update, then check syntax and service availability.”</p></blockquote><p>AI reads the configuration, prepares a diff, uses file tools to check for conflicting writes, and runs service-specific validation and reload commands. Your workflow needs to arrange backups, approval, and recovery steps.</p><p><strong>What you get:</strong> A record of what changed, which checks passed, and whether the service recovered—not just a message saying the command ran.</p><h3 id="_4-routine-automation-get-inspection-results-in-chat" tabindex="-1">4. Routine automation: get inspection results in chat <a class="header-anchor" href="#_4-routine-automation-get-inspection-results-in-chat" aria-label="Permalink to &quot;4. Routine automation: get inspection results in chat&quot;">​</a></h3><blockquote><p>“Summarize server health daily. When an alert arrives, investigate first, act only within the pre-approved scope, and report the result.”</p></blockquote><p>Connect Nezha MCP to a configured assistant schedule or alert-notification workflow. AI can then gather current state, investigate issues, and deliver a summary when needed. The assistant or external workflow provides scheduling, alert reception, and messaging.</p><p><strong>What you get:</strong> Routine inspection summaries and incident responses informed by current conditions. You define the scope of automated action; enabling MCP does not hand over autonomous control by default.</p><h2 id="choose-your-familiar-ai-tool" tabindex="-1">Choose your familiar AI tool <a class="header-anchor" href="#choose-your-familiar-ai-tool" aria-label="Permalink to &quot;Choose your familiar AI tool&quot;">​</a></h2><ul><li><strong>Codex:</strong> Inspect the running server environment and verify changes while working on code, configuration, or deployment issues.</li><li><strong>Claude Code:</strong> Combine log inspection, diagnostic commands, and file changes in a step-by-step troubleshooting conversation.</li><li><strong>OpenClaw:</strong> Start inspections from chat, then combine configured schedules and messaging channels for routine operations.</li></ul><p>Use a client that supports HTTP MCP and Bearer tokens. OpenClaw needs an MCP client available to its current runtime or mcporter. See <a href="/en_US/guide/mcp.html#connect-clients">Connect AI clients</a> for setup.</p><h2 id="get-started-with-one-status-check" tabindex="-1">Get started with one status check <a class="header-anchor" href="#get-started-with-one-status-check" aria-label="Permalink to &quot;Get started with one status check&quot;">​</a></h2><p><strong>New to Nezha?</strong> <a href="/en_US/guide/dashboard.html">Install Dashboard</a> and an <a href="/en_US/guide/agent.html">Agent</a> to bring your server online. If your servers are already connected:</p><ol><li><strong>Enable access:</strong> Enable MCP in Nezha and create a dedicated personal access token (PAT), limiting access to the servers and tools you need.</li><li><strong>Connect your assistant:</strong> Follow the <a href="/en_US/guide/mcp.html#connect-clients">setup guide</a> and confirm it can read the authorized server list.</li><li><strong>Try a read-only query:</strong> Send the request below and check the returned servers and state. Add command execution and file-write access later as needed.</li></ol><blockquote><p>“List the servers I can view and summarize their online status and disk usage. Do not run commands or change files. List any unknown states separately.”</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Start with queries, then add automation</p><p>MCP is disabled by default. Commands run with the permissions of the Nezha Agent on the server; execution access is not read-only access. Arrange client-side confirmation for operations that stop services, delete data, or change configuration. See <a href="/en_US/guide/mcp.html">permissions and security</a> and <a href="/en_US/guide/security.html">data privacy</a>.</p></div><h2 id="faq" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;Frequently asked questions {#faq}&quot;">​</a></h2><h3 id="what-is-nezha-mcp" tabindex="-1">What is Nezha MCP? <a class="header-anchor" href="#what-is-nezha-mcp" aria-label="Permalink to &quot;What is Nezha MCP?&quot;">​</a></h3><p>Nezha MCP is a standard tool interface connecting AI assistants to servers. It provides server inventory, current state, remote commands, and file operations. AI interprets your goal; Nezha supplies the operational tools.</p><h3 id="can-i-use-it-with-codex-openclaw-and-claude-code" tabindex="-1">Can I use it with Codex, OpenClaw, and Claude Code? <a class="header-anchor" href="#can-i-use-it-with-codex-openclaw-and-claude-code" aria-label="Permalink to &quot;Can I use it with Codex, OpenClaw, and Claude Code?&quot;">​</a></h3><p>Clients supporting HTTP MCP and Bearer tokens can connect. Codex and Claude Code support remote MCP. OpenClaw needs an MCP client available to its current runtime or mcporter.</p><h3 id="does-nezha-include-an-ai-model-or-chatbot" tabindex="-1">Does Nezha include an AI model or chatbot? <a class="header-anchor" href="#does-nezha-include-an-ai-model-or-chatbot" aria-label="Permalink to &quot;Does Nezha include an AI model or chatbot?&quot;">​</a></h3><p>No model is bundled. Nezha supplies monitoring and operations tools; your chosen AI client provides the model, conversation, reasoning, and workflow orchestration.</p><h3 id="can-mcp-configure-alerts-query-historical-metrics-or-manage-every-dashboard-setting" tabindex="-1">Can MCP configure alerts, query historical metrics, or manage every Dashboard setting? <a class="header-anchor" href="#can-mcp-configure-alerts-query-historical-metrics-or-manage-every-dashboard-setting" aria-label="Permalink to &quot;Can MCP configure alerts, query historical metrics, or manage every Dashboard setting?&quot;">​</a></h3><p>MCP provides server state, command, and file tools. Alert and task configuration, historical metrics, and other Dashboard settings require the Nezha admin UI or REST API.</p><h3 id="can-i-automate-incident-response" tabindex="-1">Can I automate incident response? <a class="header-anchor" href="#can-i-automate-incident-response" aria-label="Permalink to &quot;Can I automate incident response?&quot;">​</a></h3><p>You can build workflows for diagnosis, authorized remediation, and verification. The client or external workflow provides scheduling, alert reception, and action confirmation. Nezha trigger tasks can execute reviewed scripts.</p><h3 id="can-data-still-reach-an-ai-provider-when-nezha-is-self-hosted" tabindex="-1">Can data still reach an AI provider when Nezha is self-hosted? <a class="header-anchor" href="#can-data-still-reach-an-ai-provider-when-nezha-is-self-hosted" aria-label="Permalink to &quot;Can data still reach an AI provider when Nezha is self-hosted?&quot;">​</a></h3><p>Dashboard and server Agents can be self-hosted. With an external model, the client may send prompts, tool results, logs, or file contents to the model provider. Data handling depends on model deployment and the client&#39;s policies.</p>',44))]))}});export{h as __pageData,u as default};
